        function solve(input) {
          const [s, t] = input.trim().split("\n").map((x) => x.trim());
          let i = 0;
          for (let j = 0; j < t.length && i < s.length; j++) {
            if (s[i] === t[j]) i++;
          }
          return i === s.length ? "true" : "false";
        }
