        function solve(input) {
          const [m, n] = input.trim().split(/\s+/).map(Number);
          const MOD = 1000000007;
          const dp = new Array(n).fill(1);
          for (let i = 1; i < m; i++) {
            for (let j = 1; j < n; j++) {
              dp[j] = (dp[j] + dp[j - 1]) % MOD;
            }
          }
          return String(dp[n - 1]);
        }
